CREATE TABLE product_variant (id BIGINT NOT NULL AUTO_INCREMENT,product_id BIGINT NOT NULL,sku VARCHAR(100) NOT NULL,combination_key VARCHAR(500) NOT NULL,option_summary VARCHAR(500) NOT NULL,additional_price DECIMAL(19,2) NOT NULL,stock_quantity INT NOT NULL,sale_status VARCHAR(30) NOT NULL,sort_order INT NOT NULL,created_at DATETIME(6) NOT NULL,updated_at DATETIME(6) NOT NULL,PRIMARY KEY(id),CONSTRAINT uk_product_variant_sku UNIQUE(sku),CONSTRAINT uk_product_variant_combination UNIQUE(product_id,combination_key));
CREATE INDEX idx_product_variant_product ON product_variant(product_id);
